const servers = $json.servers || [];
const inputNode = $('Вхід: команда з агента');

// 1. identifier, якщо є
let target = String(inputNode.item.json.identifier || "").trim();
const query = String(inputNode.item.json.query || "").trim();
const parts = query.split(' ');

// 2. Якщо identifier пустий — беремо назву з query
if (!target) {
  if (parts.length > 1) {
    target = parts[1].trim();
  } else {
    const extractedId = query.match(/\d+/);
    if (extractedId) target = extractedId[0];
  }
}

// 2b. list_snapshots без сервера — показати знімки всіх серверів
if (query.toLowerCase().startsWith('list_snapshots') && !target) {
  return { id: 0, action: 'list_snapshots', name: '(all)', newType: '', skipSnapshot: false };
}

// 3. Шукаємо збіг у списку від Hetzner
const match = servers.find(s =>
  String(s.id) === target ||
  s.public_net.ipv4.ip === target ||
  s.name === target
);

if (!match) {
  return {
    error: "Сервер не знайдено. Перевірте назву (list_servers).",
    searched_for: target
  };
}

// 4. Визначаємо дію
let action = "unknown";
const q = query.toLowerCase();

if (q.startsWith('reboot')) action = "reboot";
else if (q.startsWith('create_snapshot')) action = "create_image";
else if (q.startsWith('poweron')) action = "poweron";
else if (q.startsWith('poweroff')) action = "poweroff";
else if (q.startsWith('delete_server')) action = "delete_server";
else if (q.startsWith('change_type')) action = "change_type";
else if (q.startsWith('delete_snapshot')) action = "delete_snapshot";
else if (q.startsWith('list_snapshots')) action = "list_snapshots";

// Без автоснепшота лише для delete_server і лише якщо явно запитано
const skipSnapshot = action === 'delete_server' && (q.indexOf('no_snapshot') >= 0 || q.indexOf('without_snapshot') >= 0);

// 5. Захист: деструктивні дії лише для серверів cvat-*
const destructive = ['delete_server', 'change_type', 'poweroff'];
if (destructive.includes(action) && !String(match.name).startsWith('cvat-')) {
  return {
    error: "Заборонено: сервер " + match.name + " не є CVAT-сервером (назва має починатися з cvat-). Цю дію виконати не можу.",
    searched_for: target
  };
}

// 5b. Сервер захищено від видалення в Hetzner — не видаляємо і не робимо зайвий снепшот
if (action === 'delete_server' && match.protection && match.protection.delete) {
  return {
    error: "Сервер " + match.name + " захищено від видалення 🔒. Спочатку зніміть захист (інструмент розширених функцій, дія unprotect), потім повторіть видалення.",
    searched_for: target
  };
}

// 6. Новий тип для change_type (наприклад: "change_type cvat-test15 cpx21")
let newType = "";
if (action === "change_type" && parts.length > 2) {
  newType = parts[2].trim();
}

return {
  id: match.id,
  action: action,
  name: match.name,
  newType: newType,
  skipSnapshot: skipSnapshot
};

const action = $node["Маршрут: дія над сервером"].json.action;
const name = $node["Визначити сервер і дію"].json.name;
return {
  success: true,
  message: `Команду [${action}] для сервера ${name} успішно відправлено в Hetzner.`,
  output: `Action ${action} executed`
};

const action = $node["Маршрут: дія над сервером"].json.action;
const name = $node["Визначити сервер і дію"].json.name;
return {
  success: true,
  message: `Команду [${action}] для сервера ${name} успішно відправлено в Hetzner.`,
  output: `Action ${action} executed`
};

const action = $node["Маршрут: дія над сервером"].json.action;
const name = $node["Визначити сервер і дію"].json.name;
return {
  success: true,
  message: `Команду [${action}] для сервера ${name} успішно відправлено в Hetzner.`,
  output: `Action ${action} executed`
};

const serverName = $node["Визначити сервер і дію"].json.name;
const imageId = ($json.image && $json.image.id) ? $json.image.id : '?';
const msg = 'Створення снепшота для сервера ' + serverName + ' розпочато (ID снепшота: ' + imageId + '). Зазвичай це займає 5–15 хвилин; готовність перевірте командою «список снепшотів».';
return { success: true, message: msg, output: msg };

const images = $json.images || [];
const resolver = $('Визначити сервер і дію').first().json;
const serverName = resolver.name;
const serverId = String(resolver.id);
const showAll = serverName === '(all)';

const fmt = i => '• **ID: ' + i.id + '** — ' + (i.description || 'без опису') + ' (сервер: ' + (i.created_from && i.created_from.name ? i.created_from.name : (i.bound_to || 'не вказано')) + ', ' + (i.created || '').slice(0, 10) + ', ' + (i.image_size ? Math.round(i.image_size * 10) / 10 + ' GB' : '?') + ')';

if (images.length === 0) {
  return {
    success: true,
    message: '📸 Наразі у вашому акаунті Hetzner не знайдено жодного знімка (snapshot).',
    output: 'No snapshots found at all'
  };
}

if (showAll) {
  const list = images.map(fmt).join('\n');
  return {
    success: true,
    message: '📸 Знімки всіх серверів (' + images.length + '):\n' + list,
    output: list
  };
}

const filtered = images.filter(i =>
  String(i.bound_to) === serverId ||
  (i.created_from && i.created_from.name === serverName) ||
  (i.description && i.description.toLowerCase().includes(serverName.toLowerCase()))
);

if (filtered.length === 0) {
  return {
    success: true,
    message: '📸 Для сервера ' + serverName + ' знімків немає.',
    output: 'No snapshots for ' + serverName
  };
}

const list = filtered.map(fmt).join('\n');
return {
  success: true,
  message: '✅ Знімки сервера ' + serverName + ' (' + filtered.length + '):\n' + list,
  output: list
};

const name = $('Визначити сервер і дію').first().json.name;
const newType = $('Визначити сервер і дію').first().json.newType;
const snap = $('Автоснепшот: перед зміною тарифу').first().json.snapshot_id;
const msg = '✅ Сервер ' + name + ' успішно змінено на тариф ' + newType + '. Перед зміною створено автоснепшот (ID ' + snap + '). Я вимкнув сервер, змінив тип і увімкнув назад.';
return { success: true, message: msg, output: msg };

const serverName = $('Визначити сервер і дію').first().json.name;
let snap = '';
try {
  snap = $('Автоснепшот: перед видаленням').first().json.snapshot_id || '';
} catch (e) {}
let msg = 'Сервер ' + serverName + ' успішно видалено з Hetzner та Cloudflare. Статус у таблиці оновлено на Deleted.';
if (snap) {
  msg += ' Перед видаленням створено автоснепшот (ID ' + snap + '); щоб його видалити пізніше: «видали снепшот ' + snap + '».';
} else {
  msg += ' Видалено БЕЗ снепшота за вашим рішенням. Автоматичні бекапи Hetzner цього сервера також видалено.';
}
return { success: true, message: msg, output: msg };

const servers = $json.servers || [];

if (servers.length === 0) {
  return {
    success: true,
    output: "Наразі у вашому акаунті Hetzner немає активних серверів."
  };
}

const list = servers.map(s => 
  `• *${s.name}* | ID: ${s.id} | IP: ${s.public_net?.ipv4?.ip || 'N/A'} | Тип: ${s.server_type?.name || 'N/A'} | Статус: ${s.status}`
).join('\n');

return {
  success: true,
  output: `Ось список серверів:\n\n${list}`
};

const e = $json.error;
const msg = e ? ('⚠️ ' + e + ($json.searched_for ? ' (шукали: ' + $json.searched_for + ')' : '')) : '⚠️ Невідома команда, дію не виконано.';
return { success: false, message: msg, output: msg };

const types = ($json.server_types || []).filter(t => !t.deprecated);
const LOCS = ['nbg1', 'fsn1', 'hel1'];
const rows = [];
for (const t of types) {
  let p = null;
  for (const l of LOCS) {
    p = (t.prices || []).find(x => x.location === l);
    if (p) break;
  }
  if (!p) continue;
  const price = Math.round(parseFloat(p.price_monthly.gross) * 100) / 100;
  const arch = t.architecture === 'arm' ? ' (ARM)' : '';
  const kind = t.cpu_type === 'dedicated' ? ' (Dedicated)' : '';
  rows.push({ price, line: '• *' + t.name + '*: ' + t.cores + ' vCPU' + arch + kind + ', ' + t.memory + ' GB RAM, ' + t.disk + ' GB — *' + price.toFixed(2) + ' €/міс*' });
}
rows.sort((a, b) => a.price - b.price);
const list = rows.map(r => r.line).join('\n');
const msg = 'Доступні тарифи (ціна за місяць з ПДВ, ЄС-локації; від дешевших до дорожчих):\n' + list;
return { success: true, message: msg, output: msg };
